+    expect(getImagesForEntitiesGrid(null)).toEqual([]);
+  });
+
+  test('returns empty array for undefined input', () => {
+    expect(getImagesForEntitiesGrid(undefined)).toEqual([]);
+  });
+
+  test('returns empty array for empty array input', () => {
